package main

import (
	"fmt"
	"time"
	"github.com/nats-io/nats-server/v2/server"
)

func main() {
	// Test 1: Parse configuration with handshake_first duration for leafnodes
	conf := `
	port: -1
	leafnodes {
		port: -1
		tls {
			cert_file: "../test/configs/certs/server-cert.pem"
			key_file: "../test/configs/certs/server-key.pem"
			ca_file: "../test/configs/certs/ca.pem"
			handshake_first: 500ms
		}
	}
	`

	opts, err := server.ProcessConfigFileOption(func() (string, error) {
		return conf, nil
	})

	if err != nil {
		fmt.Printf("Error parsing config: %v\n", err)
		return
	}

	// Check if TLSHandshakeFirst is set
	if !opts.LeafNode.TLSHandshakeFirst {
		fmt.Println("ERROR: TLSHandshakeFirst should be true")
		return
	}
	fmt.Println("✓ TLSHandshakeFirst is true")

	// Check if TLSHandshakeFirstFallback is set correctly
	expectedFallback := 500 * time.Millisecond
	if opts.LeafNode.TLSHandshakeFirstFallback != expectedFallback {
		fmt.Printf("ERROR: TLSHandshakeFirstFallback should be %v, got %v\n", expectedFallback, opts.LeafNode.TLSHandshakeFirstFallback)
		return
	}
	fmt.Printf("✓ TLSHandshakeFirstFallback is %v\n", opts.LeafNode.TLSHandshakeFirstFallback)

	// Test 2: Parse configuration with remote leafnode
	conf2 := `
	port: -1
	leafnodes {
		port: -1
		remotes [
			{
				url: "tls://localhost:4222"
				tls {
					cert_file: "../test/configs/certs/server-cert.pem"
					key_file: "../test/configs/certs/server-key.pem"
					ca_file: "../test/configs/certs/ca.pem"
					handshake_first: 300ms
				}
			}
		]
	}
	`

	opts2, err := server.ProcessConfigFileOption(func() (string, error) {
		return conf2, nil
	})

	if err != nil {
		fmt.Printf("Error parsing config2: %v\n", err)
		return
	}

	if len(opts2.LeafNode.Remotes) == 0 {
		fmt.Println("ERROR: No remotes parsed")
		return
	}

	remote := opts2.LeafNode.Remotes[0]
	if !remote.TLSHandshakeFirst {
		fmt.Println("ERROR: Remote TLSHandshakeFirst should be true")
		return
	}
	fmt.Println("✓ Remote TLSHandshakeFirst is true")

	expectedRemoteFallback := 300 * time.Millisecond
	if remote.TLSHandshakeFirstFallback != expectedRemoteFallback {
		fmt.Printf("ERROR: Remote TLSHandshakeFirstFallback should be %v, got %v\n", expectedRemoteFallback, remote.TLSHandshakeFirstFallback)
		return
	}
	fmt.Printf("✓ Remote TLSHandshakeFirstFallback is %v\n", remote.TLSHandshakeFirstFallback)

	fmt.Println("\nAll tests passed!")
}
EOFTEST

